/// Runs `fut` to completion on a separate current-thread runtime (the caller's, not the library's).
fn block<F: Future>(fut: F) -> F::Output {
    let caller = tokio::runtime::Builder::new_current_thread()
        .enable_time()
        .build()
        .expect("caller runtime");
    caller.block_on(async { tokio::time::timeout(LIMIT, fut).await.expect("timed out") })
}

fn spec(pty: bool) -> Spec {
    Spec {
        program: "/bin/fixture".into(),
        argv: vec!["fixture".into(), "arg with space".into()],
        env: vec![("K".into(), "V".into())],
        cwd: std::env::temp_dir(),
        mode: if pty {
            Mode::Pty(PtySize { cols: 100, rows: 30 })
        } else {
            Mode::Pipe
        },
        stdin: Stdin::Pipe,
        merge_stderr: false,
        grace: Duration::from_millis(1500),
        verbatim: None,
    }
}

pub(super) fn spawn_on(sup: &Arc<Gen>, spec: &Spec) -> Result<Spawned, Error> {
    sup.home()?;
    let pty = match spec.mode {
        Mode::Pty(size) => Some((size.cols, size.rows)),
        Mode::Pipe => None,
    };
    let piped = pty.is_none() && spec.stdin == Stdin::Pipe;
    let merged = pty.is_none() && spec.merge_stderr;
    let (host, handles, fds) = match pty {
        Some(_) => ([None, None, None], [0; 3], Vec::new()),
        None => {
            let created = pipes(piped, merged);
            let (host, child) = created.map_err(|e| Error::host_ends("cannot create the child's pipes", &e))?;
            let given = sup.chan().hand_over(child);
            let (handles, fds) = given.map_err(|e| Error::host_ends("cannot pass the pipes to the supervisor", &e))?;
            (host, handles, fds)
        }
    };

/// The host's and the child's ends, in stdin, stdout, stderr order (stdout is always a pipe).
type Ends3 = [Option<Pipe>; 3];

fn pipes(piped: bool, merged: bool) -> std::io::Result<(Ends3, Ends3)> {
    let (in_host, in_child) = match piped {
        true => sys::pipe().map(|(r, w)| (Some(w), Some(r)))?,
        false => (None, None),
    };
    let (out_r, out_w) = sys::pipe()?;
    let (err_host, err_child) = match merged {
        true => (None, None),
        false => sys::pipe().map(|(r, w)| (Some(r), Some(w)))?,
    };
    Ok(([in_host, Some(out_r), err_host], [in_child, Some(out_w), err_child]))
}

fn pipe_ends_travel_with_the_spawn_frame() {
    let (sup, mut peer) = pair(BOUND);
    let mut big = spec(false);
    big.env = (0..2000)
        .map(|i| (format!("VAR_{i}").into(), "x".repeat(300).into()))
        .collect();
    let caller = {
        let sup = sup.clone();
        std::thread::spawn(move || spawn_on(&sup, &big))
    };
    let Msg::Spawn(s) = peer.recv() else {
        panic!("expected Spawn")
    };
    assert_eq!(
        (s.env.len(), s.stdin, s.stderr, s.pty),
        (2000, Slot::Pipe, Slot::Pipe, None)
    );
    let fds: Vec<OwnedFd> = peer.fds.drain(..).collect();
    assert_eq!(fds.len(), 3, "one descriptor per pipe, sent once");

/// Starts a PTY tree `id`; the peer returns a pipe end as the "master".
pub(super) fn pty_spawn(sup: &Arc<Gen>, peer: &mut Peer, id: u64) -> (Spawned, OwnedFd) {
    let caller = {
        let sup = sup.clone();
        std::thread::spawn(move || spawn_on(&sup, &spec(true)))
    };
    let Msg::Spawn(s) = peer.recv() else {
        panic!("expected Spawn")
    };
    assert_eq!((s.pty, peer.fds.len()), (Some((100, 30)), 0));
    let (master, _other) = pipe().unwrap();
    let reply = Msg::Spawned {
        req: s.req,
        id,
        pid: 7,
        pty_ends: [1, 0],
    };
    let mut bytes = Vec::new();
    omni_proto::encode(&reply, &mut bytes).unwrap();
    super::platform::write(&mut peer.end, &bytes, Some(&master));
    (caller.join().unwrap().unwrap(), master)

