/// `cwd` made absolute against the host's working directory (`host`, read only when needed). A Windows
/// drive-relative cwd is refused before anything is read.
pub(super) fn absolute(
    cwd: Option<&Path>,
    host: impl FnOnce() -> io::Result<PathBuf>,
    os: Os,
) -> Result<PathBuf, Error> {
    let Some(given) = cwd else {
        return host().map_err(|err| Error::host_cwd_unreadable(None, &err));
    };
    match path::kind(given.as_os_str(), os) {
        Kind::Absolute => Ok(given.to_path_buf()),
        Kind::DriveRelative => Err(Error::drive_relative_cwd(given)),
        Kind::RootRelative | Kind::Relative => {
            let host = host().map_err(|err| Error::host_cwd_unreadable(cwd, &err))?;
            path::join(&host, given.as_os_str(), os).ok_or_else(|| Error::drive_relative_cwd(given))
        }
    }
}

/// `dir` checked to be a directory (symlinks followed). `given` is the cwd as passed, for the message.
pub(super) fn directory(given: Option<&Path>, dir: PathBuf) -> Result<PathBuf, Error> {
    match std::fs::metadata(&dir) {
        Ok(meta) if meta.is_dir() => Ok(dir),
        Ok(_) => Err(Error::cwd_not_directory(given, &dir)),
        Err(err) if matches!(err.kind(), io::ErrorKind::NotFound | io::ErrorKind::NotADirectory) => {
            Err(Error::cwd_missing(given, &dir))
        }
        Err(err) => Err(Error::cwd_inaccessible(given, &dir, &err)),
    }
}

/// The supervisor could not start `program`; `code` is the one its reply maps to.
pub(crate) fn spawn_refused(code: ErrorCode, program: &str, msg: &str, errno: i32) -> Error {
    Error::new(code, format!("cannot start {program}: {msg} (os error {errno})."))
}

/// The host could not create, pass or take the child's pipe or terminal ends.
pub(crate) fn host_ends(what: &str, err: &io::Error) -> Error {
    io_error(format!(
        "{what}: {err}. The process is probably out of file descriptors or handles; close some and retry."
    ))
}

pub(crate) fn terminal_never_started() -> Error {
    io_error("the terminal program never started (its exec failed), so it has no exit status.".to_string())
}

pub(crate) fn resize_after_exit(cols: u16, rows: u16) -> Error {
    Error::new(
        ErrorCode::Closed,
        format!("cannot resize the terminal to {cols}x{rows}: its program already exited."),
    )
}

impl Tree {
    /// Unix PTY roots: lets the held root exec, once the host's reader runs, and returns when exec
    /// succeeded or failed (the second bounded round trip of a PTY spawn). A no-op elsewhere.
    pub(crate) fn go(&self) -> Result<(), Error> {
        self.sup.home()?;
        match self.hold.go(self.sup.bound() * 2, || self.send_go())? {
            GoEnd::Ok => Ok(()),
            GoEnd::Failed(code, errno, msg) => Err(failed(code, errno, &msg, "the terminal program")),
            GoEnd::Refused(ack) => Err(self.refused("Go", &Answer::Ack(ack))),
            GoEnd::Gone => Err(self.sup.gone()),
        }
    }

    /// Resolves at root exit; every call returns the same value.
    pub(crate) async fn exited(&self) -> Result<RootExit, Error> {
        self.sup.home()?;
        let mut rx = self.life.subscribe();
        let life = match rx.wait_for(|l| l.exit.is_some() || l.lost).await {
            Ok(life) => *life,
            Err(_) => *self.life.borrow(),
        };
        life.exit.ok_or_else(|| self.lost())
    }

/// The `Go` round trip. `Err` only when nothing was sent (the generation is alive: every failure
/// after sending ends it), so the root stays held.
fn send_go(&self) -> Result<GoEnd, Error> {
    let id = self.id;
    match self.sup.call(Want::Go, id, |req| Msg::Go { req, id }, Vec::new()) {
        Err(e) if self.sup.alive() => Err(e),
        Err(_) => Ok(GoEnd::Gone),
        Ok(Answer::Ack(Ack::Ok)) => Ok(GoEnd::Ok),
        Ok(Answer::Failed { code, errno, msg }) => {
            self.life.send_modify(|l| (l.gone, l.lost) = (true, true));
            Ok(GoEnd::Failed(code, errno, msg))
        }
        Ok(Answer::Ack(ack)) => Ok(GoEnd::Refused(ack)),
        Ok(_) => Ok(GoEnd::Refused(Ack::Error)),
    }
}

/// Why no exit will come: the generation died, or the root never started.
fn lost(&self) -> Error {
    match self.sup.alive() {
        false => self.sup.gone(),
        true => Error::terminal_never_started(),
    }

/// The error for a `SpawnFailed` reply about `program`.
pub(super) fn failed(code: FailCode, errno: i32, msg: &str, program: &str) -> Error {
    let code = match code {
        FailCode::NotFound => ErrorCode::NotFound,
        FailCode::NotExecutable => ErrorCode::NotExecutable,
        FailCode::BadCwd => ErrorCode::InvalidCwd,
        FailCode::Invalid => ErrorCode::InvalidArgument,
        FailCode::Io => ErrorCode::Io,
    };
    Error::spawn_refused(code, program, msg, errno)
}

let (failed, _master) = pty_spawn(&sup, &mut peer, 2);
let go = std::thread::spawn(move || (failed.tree.go(), failed));
let Msg::Go { req, id: 2 } = peer.recv() else {
    panic!("expected Go")
};
let msg = "execve /bin/fixture: no such file".into();
peer.send(&Msg::SpawnFailed {
    req,
    code: FailCode::NotFound,
    errno: 2,
    msg,
});
let (result, failed) = go.join().unwrap();
assert_eq!(result.unwrap_err().code(), ErrorCode::NotFound);
assert_io(super::block(failed.tree.exited()), "never started");
super::block(failed.tree.stop(Duration::ZERO)).expect("nothing is left to stop");
assert!(sup.alive());

fn io_error(message: String) -> Error {
    Error::new(ErrorCode::Io, message)
}

/// The option on a system that has no command line to write.
pub(crate) fn verbatim_not_windows() -> Error {
    invalid(
        "windowsVerbatimArgs is set, but this is not Windows: Unix passes a list of arguments, not a command \
         line, so there is nothing to write verbatim. Set it only on Windows, and pass args elsewhere.",
    )
}

/// The option together with `args`.
pub(crate) fn verbatim_with_args(count: usize) -> Error {
    invalid(&format!(
        "windowsVerbatimArgs is set together with {count} args, but the verbatim text is the whole command line \
         after the program. Put every argument into windowsVerbatimArgs, or pass args without it."
    ))
}

/// A NUL in the verbatim text.
pub(crate) fn nul_in_verbatim(at: usize) -> Error {
    nul(
        "windowsVerbatimArgs (not shown: arguments often carry secrets)",
        "windowsVerbatimArgs",
        at,
    )
}

/// The program resolved to a batch file, which Windows would run through `cmd.exe` with the text unescaped.
pub(crate) fn verbatim_batch(command: &OsStr, resolved: &Path) -> Error {
    invalid(&format!(
        "windowsVerbatimArgs is set, but command {command:?} is the batch file \"{}\", which only cmd.exe can \
         run, and the library never adds cmd.exe to a verbatim command line. Name cmd.exe as the command and \
         write the batch file into windowsVerbatimArgs (e.g. /d /s /c \"\"script.cmd\" arg\"), or pass args \
         without windowsVerbatimArgs to get batch-safe quoting.",
        resolved.display()
    ))

if let Some(tail) = &req.verbatim {
    if os != Os::Windows {
        return Err(Error::verbatim_not_windows());
    }
    if !req.args.is_empty() {
        return Err(Error::verbatim_with_args(req.args.len()));
    }
    if let Some(at) = nul(tail) {
        return Err(Error::nul_in_verbatim(at));
    }
}

/// A verbatim command line (amendment WP8b) never reaches a batch file: Windows would run it through `cmd.exe` with
/// the caller's tail unescaped, so the caller must name `cmd.exe` itself. `resolved` is the program as resolved; its
/// last component is compared the way Windows opens it (trailing dots and spaces dropped, any case).
pub(super) fn verbatim_program(command: &OsStr, resolved: &Path, os: Os) -> Result<(), Error> {
    let bytes = resolved.as_os_str().as_encoded_bytes();
    let name = match bytes.iter().rposition(|&b| path::is_sep(b, os)) {
        Some(at) => bytes.get(at + 1..).unwrap_or_default(),
        None => bytes,
    };
    let end = name
        .iter()
        .rposition(|&b| b != b'.' && b != b' ')
        .map_or(0, |last| last + 1);
    let name = name.get(..end).unwrap_or_default();
    let ext = name
        .len()
        .checked_sub(4)
        .and_then(|at| name.get(at..))
        .unwrap_or_default();
    if os == Os::Windows && (ext.eq_ignore_ascii_case(b".bat") || ext.eq_ignore_ascii_case(b".cmd")) {
        return Err(Error::verbatim_batch(command, resolved));
    }
    Ok(())
}

/// Validates `req` per contract §3 (InvalidArgument / InvalidCwd), builds the final environment and resolves the program
/// against the child's final PATH (NotFound / NotExecutable). Never starts or executes anything.
pub(crate) fn prepare(req: &Request) -> Result<Spec, Error> {
    validate::check(req, HOST)?;
    let env = env::build(req);
    let cwd = validate::cwd(req)?;
    let program = resolve::program(&req.program, &env, &cwd)?;
    if req.verbatim.is_some() {
        validate::verbatim_program(&req.program, &program, HOST)?;
    }

/// Absolute path of the program to execute. Never executes anything.
pub(super) fn program(program: &OsStr, env: &[(OsString, OsString)], cwd: &Path) -> Result<PathBuf, Error> {
    find(program, env, cwd, HOST, probe)
}
